const defaults = [
  { id: 1, icon: '🍜', title: '新宿でラーメン食べよう', time: '30分後', place: '新宿駅東口・1.2km', current: 2, max: 4, host: 'ケンタ', rating: '★ 4.9', match: 94, hot: true, photo: 0, desc: '気になっていた煮干しラーメンへ。初参加も大歓迎です！' },
  { id: 2, icon: '🏃', title: '代々木公園を軽くランニング', time: '1時間後', place: '代々木公園・2.4km', current: 3, max: 5, host: 'Miki', rating: '★ 4.8', match: 88, photo: 1, desc: '会話できるくらいのペースで5km走ります。' },
  { id: 3, icon: '☕', title: '作業仲間募集・駅前カフェ', time: '3時間後', place: '渋谷駅・3.1km', current: 1, max: 3, host: 'Sora', rating: '★ 4.7', match: 81, photo: 2, desc: '各自作業しつつ、ときどき雑談しましょう。' },
  { id: 4, icon: '🏍️', title: '夕方のショートツーリング', time: '3時間後', place: '世田谷・7.8km', current: 2, max: 4, host: 'Ryo', rating: '★ 5.0', match: 79, photo: 3, desc: '安全第一でゆっくり走ります。初心者歓迎。' },
];

const saved = JSON.parse(localStorage.getItem('hangout-now-demo') || 'null');
const hangouts = saved?.hangouts || defaults;
const app = document.querySelector('#app');
let activeFilter = 'おすすめ';
let activeScreen = 'home';
const joined = new Set(saved?.joined || []);
const chats = saved?.chats || {};
const API_URL = globalThis.HANGOUT_NOW_CONFIG?.apiUrl || 'http://localhost:3000';
const DEMO_ACCOUNTS = globalThis.HANGOUT_NOW_CONFIG?.demoAccounts || null;
let session = JSON.parse(localStorage.getItem('hangout-now-session') || 'null');
let demoRole = localStorage.getItem('hangout-now-demo-role');
const areas={新宿:{latitude:35.6901,longitude:139.7005},渋谷:{latitude:35.6580,longitude:139.7016},池袋:{latitude:35.7295,longitude:139.7109},東京:{latitude:35.6812,longitude:139.7671}};
let userLocation=saved?.userLocation||null;
let unreadNotifications=0;
let realtimeSocket=null;
if (new URLSearchParams(location.search).has('resetAuth')) { localStorage.removeItem('hangout-now-session'); session = null; }

function portraitClass(photo) { return `host-${photo}`; }
function photoStyle(url) { return url ? ` style="background-image:url('${url}')"` : ''; }

function persist() { localStorage.setItem('hangout-now-demo', JSON.stringify({ hangouts, joined: [...joined], chats, userLocation })); }
function navigate(screen) { if (!session) { authScreen(); return; } activeScreen = screen; ({ home, mapScreen, chatScreen, profileScreen }[screen])(); }
function connectRealtime(){if(!session)return;if(typeof io==='undefined'){if(!document.querySelector('#socket-client')){const script=document.createElement('script');script.id='socket-client';script.src=`${API_URL}/socket.io/socket.io.js`;script.onload=connectRealtime;document.head.append(script)}return}realtimeSocket?.disconnect();realtimeSocket=io(API_URL,{auth:{token:session.accessToken},reconnection:true,reconnectionAttempts:Infinity,reconnectionDelay:800,reconnectionDelayMax:8000});realtimeSocket.on('connect',()=>{document.body.classList.remove('realtime-offline');loadNotificationCount()});realtimeSocket.on('disconnect',()=>document.body.classList.add('realtime-offline'));realtimeSocket.on('notification',async(item)=>{unreadNotifications+=1;renderBadge();toast(item.title);if(document.visibilityState==='hidden'&&Notification.permission==='granted')new Notification(item.title,{body:item.body});if(activeScreen==='chatScreen'&&['CHAT_MESSAGE','DIRECT_MESSAGE'].includes(item.type))await chatScreen()});realtimeSocket.on('notifications:changed',loadNotificationCount)}
async function loadNotificationCount(){try{const data=await api('/notifications');unreadNotifications=data.unreadCount;renderBadge();return data}catch{return null}}
function renderBadge(){const badge=document.querySelector('.notification-badge');if(badge){badge.textContent=unreadNotifications>99?'99+':String(unreadNotifications);badge.classList.toggle('hidden',!unreadNotifications)}}

async function api(path, options = {}) {
  const response = await fetch(`${API_URL}${path}`, { ...options, headers: { 'content-type': 'application/json', ...(session?.accessToken ? { authorization: `Bearer ${session.accessToken}` } : {}), ...options.headers } });
  if(response.status===401&&session?.refreshToken&&!options._retried){const refreshed=await fetch(`${API_URL}/auth/refresh`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({refreshToken:session.refreshToken})});if(refreshed.ok){session=await refreshed.json();saveSession();connectRealtime();return api(path,{...options,_retried:true})}localStorage.removeItem('hangout-now-session');session=null;authScreen();throw new Error('セッションの有効期限が切れました')}
  const data = response.status === 204 ? null : await response.json().catch(() => null);
  if (!response.ok) throw new Error(Array.isArray(data?.message) ? data.message[0] : data?.message || 'APIへ接続できませんでした');
  return data;
}
async function loadHangouts() {
  if (!session) return;
  const query=userLocation?`?latitude=${userLocation.latitude}&longitude=${userLocation.longitude}&radiusKm=50`:'';
  const rows = await api(`/hangouts${query}`);
  hangouts.splice(0, hangouts.length, ...rows.map((h, i) => ({ id:h.id, hostUserId:h.hostUserId, status:h.status, startAt:h.startAt, icon:{FOOD:'🍜',RUNNING:'🏃',CAFE:'☕',MOTORCYCLE:'🏍️',WALKING:'🚶'}[h.category]||'✨', title:h.title, time:timeLabel(h.startAt), place:h.locationName, meetingPlaceName:h.meetingPlaceName, meetingAddress:h.meetingAddress, navigationUrl:h.navigationUrl, latitude:h.latitude,longitude:h.longitude,publicLatitude:h.publicLatitude,publicLongitude:h.publicLongitude,locationPrecision:h.locationPrecision,distanceKm:h.distanceKm,current:h.participantCount, max:h.maxParticipants, hostMaleCount:h.hostMaleCount, hostFemaleCount:h.hostFemaleCount, hostParticipantCount:h.hostParticipantCount, acceptedParticipants:h.acceptedParticipants||[], genderRestriction:h.genderRestriction, maxAge:h.maxAge, host:h.host.displayName, hostPhoto:h.host.profilePhoto, hostStatus:h.host.hostStatus, verified:h.host.verification==='PHONE_VERIFIED', rating:h.host.hostStatus?.averageRating?`★ ${h.host.hostStatus.averageRating}`:'評価なし', match:Math.max(70,94-i*5), photo:i%4, desc:h.description||'', hot:timeLabel(h.startAt)==='30分後', myJoinStatus:h.myJoinStatus })));
}
function timeLabel(startAt){const minutes=Math.max(0,Math.round((new Date(startAt)-Date.now())/60000));return minutes<=45?'30分後':minutes<=90?'1時間後':'3時間後'}

function authScreen(mode = 'register') {
  const register = mode === 'register';
  const demoChoices = DEMO_ACCOUNTS ? `<section class="demo-entry"><span class="demo-label">公開デモ・すべて架空のデータです</span><h2>役割を選んですぐに体験</h2><p>登録や電話番号入力は必要ありません。</p><div class="demo-buttons"><button data-demo-role="host"><b>主催者として見る</b><small>募集管理・承認を体験</small></button><button data-demo-role="guest"><b>参加者として見る</b><small>検索・チャットを体験</small></button></div><div id="demo-error" class="auth-error"></div></section>` : '';
  app.innerHTML = `<main class="phone auth-page"><div class="auth-brand">Hangout <i>Now</i></div><div class="auth-visual"><span>🍜</span><span>🏃</span><span>☕</span></div>${demoChoices}<section class="auth-card"><div class="eyebrow">今から、誰かと。</div><h1>${register ? 'アカウントを作る' : 'おかえりなさい'}</h1><p>${register ? '18歳以上の方が利用できます。' : '登録したメールアドレスでログイン'}</p><form id="auth-form"><label>メールアドレス</label><input id="email" type="email" required value="demo@example.com">${register ? '<label>表示名</label><input id="display-name" required value="Demo User"><label>生年月日</label><input id="birth-date" type="date" required value="1990-01-01">' : ''}<label>パスワード</label><input id="password" type="password" minlength="12" required value="demo-password-123"><div id="auth-error" class="auth-error"></div><button class="primary" type="submit">${register ? '無料で登録' : 'ログイン'}</button></form><button class="secondary" id="switch-auth">${register ? 'アカウントをお持ちの方はログイン' : '新しくアカウントを作る'}</button><small>登録により利用規約とプライバシーポリシーに同意します。</small><div class="policy-links"><a href="/privacy.html">プライバシー</a><a href="/terms.html">利用規約</a><a href="/community-guidelines.html">ガイドライン</a><a href="/delete-account.html">アカウント削除</a></div></section></main>`;
  document.querySelectorAll('[data-demo-role]').forEach((button)=>button.onclick=()=>demoLogin(button.dataset.demoRole,button));
  document.querySelector('#switch-auth').onclick = () => authScreen(register ? 'login' : 'register');
  document.querySelector('#auth-form').onsubmit = async (event) => { event.preventDefault(); const button=event.submitter; button.disabled=true; button.textContent='接続中…'; const body={email:document.querySelector('#email').value,password:document.querySelector('#password').value}; if(register)Object.assign(body,{displayName:document.querySelector('#display-name').value,birthDate:document.querySelector('#birth-date').value}); try{session=await api(register?'/auth/register':'/auth/login',{method:'POST',body:JSON.stringify(body)});demoRole=null;localStorage.removeItem('hangout-now-demo-role');localStorage.setItem('hangout-now-session',JSON.stringify(session));connectRealtime();loadNotificationCount();profileSetup(register)}catch(error){document.querySelector('#auth-error').textContent=error.message;button.disabled=false;button.textContent=register?'無料で登録':'ログイン'} };
}

async function demoLogin(role, button) {
  const account = DEMO_ACCOUNTS?.[role];
  if (!account) return;
  const original = button.innerHTML;
  document.querySelectorAll('[data-demo-role]').forEach((item)=>item.disabled=true);
  button.innerHTML = '<b>ログイン中…</b><small>公開デモを準備しています</small>';
  try {
    session = null;
    session = await api('/auth/login',{method:'POST',body:JSON.stringify(account)});
    demoRole = role;
    localStorage.setItem('hangout-now-demo-role',role);
    localStorage.setItem('hangout-now-session',JSON.stringify(session));
    connectRealtime();
    await Promise.all([loadNotificationCount(),loadHangouts()]);
    navigate('home');
  } catch(error) {
    document.querySelector('#demo-error').textContent=error.message;
    document.querySelectorAll('[data-demo-role]').forEach((item)=>item.disabled=false);
    button.innerHTML=original;
  }
}

function profileSetup(firstRegistration) {
  if (!firstRegistration) { navigate('home'); return; }
  app.innerHTML = `<main class="phone auth-page"><div class="auth-brand">Hangout <i>Now</i></div><section class="auth-card setup"><div class="avatar profile-photo"></div><div class="eyebrow">あと少しです</div><h1>プロフィール設定</h1><label>プロフィール写真（募集作成に必要）</label><input id="setup-photo" type="file" accept="image/jpeg,image/png,image/webp"><label>自己紹介</label><textarea id="setup-bio" rows="3">気軽にカフェやランニングへ行ける仲間を探しています。</textarea><label>よく行くエリア</label><input id="setup-area" value="新宿・渋谷"><label>興味のあること</label><div class="interest-picker"><button class="chosen">ランニング</button><button class="chosen">カフェ</button><button>バイク</button><button>AI</button><button>ラーメン</button></div><div id="setup-error" class="auth-error"></div><button class="primary" id="save-profile">プロフィールを保存</button></section></main>`;
  document.querySelectorAll('.interest-picker button').forEach((button)=>button.onclick=()=>button.classList.toggle('chosen'));
  document.querySelector('#save-profile').onclick=async()=>{try{const interests=[...document.querySelectorAll('.interest-picker .chosen')].map((button)=>button.textContent);const file=document.querySelector('#setup-photo').files[0];const profilePhoto=file?await imageData(file):undefined;session.user=await api('/users/me',{method:'PATCH',body:JSON.stringify({bio:document.querySelector('#setup-bio').value,homeArea:document.querySelector('#setup-area').value,interests,profilePhoto})});localStorage.setItem('hangout-now-session',JSON.stringify(session));navigate('home')}catch(error){document.querySelector('#setup-error').textContent=error.message}};
}

function shell(content, showFab = true) {
  const nav = [['home','ホーム'],['mapScreen','マップ'],['chatScreen','チャット'],['profileScreen','プロフィール']];
  const demoGuide=demoRole==='host'?'作成・承認・終了・★1〜5評価を操作':'参加申請・チャット・★1〜5評価を操作';
  const demoBanner=demoRole?`<div class="demo-banner"><span><b>デモ：${demoRole==='host'?'主催者':'参加者'}として体験中</b><small>${demoGuide}</small></span><div><button id="reset-demo">最初から</button><button id="switch-demo-role">役割切替</button></div></div>`:'';
  app.innerHTML = `<main class="phone">${demoBanner}<header class="top"><div class="brand">Hangout <i>Now</i></div><div class="header-actions"><button class="notification-button" aria-label="通知"><span class="notification-mark"></span><span class="notification-badge ${unreadNotifications?'':'hidden'}">${unreadNotifications}</span></button><div class="avatar"${photoStyle(session.user.profilePhoto)} aria-label="あなたのプロフィール写真"></div></div></header>${content}${showFab ? '<button class="fab" aria-label="Hangoutを作る">＋</button>' : ''}<nav class="nav">${nav.map(([screen,label])=>`<button data-screen="${screen}" class="${activeScreen===screen?'on':''}">${label}</button>`).join('')}</nav></main>`;
  const switchDemoRole=app.querySelector('#switch-demo-role');
  if(switchDemoRole)switchDemoRole.onclick=()=>{realtimeSocket?.disconnect();session=null;demoRole=null;localStorage.removeItem('hangout-now-session');localStorage.removeItem('hangout-now-demo-role');authScreen('login')};
  const resetDemo=app.querySelector('#reset-demo');if(resetDemo)resetDemo.onclick=resetPublicDemo;
  const fab = app.querySelector('.fab');
  if (fab) fab.onclick = showCreate;
  app.querySelector('.notification-button').onclick=notificationScreen;
  app.querySelectorAll('[data-screen]').forEach((button)=>button.onclick=()=>navigate(button.dataset.screen));
}

function home() {
  activeScreen = 'home';
  const visible = activeFilter === 'おすすめ' ? hangouts : hangouts.filter((h) => h.time === activeFilter);
  const filters = [['おすすめ', 'おすすめ'], ['30分後', '30分後'], ['1時間後', '1時間後'], ['3時間後', '3時間後']];
  const journey=demoRole?`<section class="demo-journey"><b>デモ：Hangoutの一連の流れ</b><ol><li>主催者が「＋」で募集を作成</li><li>役割を切り替え、参加者が申請</li><li>主催者が承認し、グループで会話</li><li>主催者が終了して双方が★1〜5から評価</li><li>双方★5なら1対1チャットを開始</li></ol><small>「【デモ手順】新宿カフェ交流会」でも途中から試せます。</small></section>`:'';
  shell(`${journey}<section class="hero"><div class="eyebrow">${userLocation?.label||'エリア未設定'}</div><h1>今から<br>何する？</h1><div class="location-tools"><button id="use-location">現在地を使う</button><select id="manual-area"><option value="">エリアを選択</option>${Object.keys(areas).map(a=>`<option ${userLocation?.label===a?'selected':''}>${a}</option>`).join('')}</select></div></section><div class="pills">${filters.map(([value, label]) => `<button class="pill ${activeFilter === value ? 'active' : ''}" data-filter="${value}">${label}</button>`).join('')}</div><div class="section-head"><h2>近くのHangout</h2><span>${visible.length}件・距離順</span></div><section class="cards">${visible.length ? visible.map(card).join('') : '<div class="empty">この時間の募集はまだありません。<br>エリアを変更して探してみてください。</div>'}</section>`);
  document.querySelector('#use-location').onclick=useCurrentLocation;
  document.querySelector('#manual-area').onchange=async(event)=>{const name=event.target.value;if(!name)return;userLocation={...areas[name],label:name,source:'manual'};persist();await loadHangouts();home()};
  document.querySelectorAll('[data-filter]').forEach((button) => button.onclick = () => { activeFilter = button.dataset.filter; home(); });
  document.querySelectorAll('.card').forEach((cardElement) => cardElement.onclick = () => detail(cardElement.dataset.id));
}

function card(h) {
  const requested = joined.has(h.id) || h.myJoinStatus === 'PENDING' || h.myJoinStatus === 'ACCEPTED';
  const conditions=`${{ANY:'だれでも',MALE_ONLY:'男性のみ',FEMALE_ONLY:'女性のみ'}[h.genderRestriction]||'だれでも'}${h.maxAge?`・${h.maxAge===29?'20代':h.maxAge===39?'30代':'50代'}まで`:''}`;
  const state=h.myJoinStatus==='PENDING'?'申請中':h.myJoinStatus==='ACCEPTED'?'承認済み':h.status==='FULL'?'満員':new Date(h.startAt)<=new Date()?'開催中':'募集中';
  return `<article class="card ${requested ? 'requested' : ''}" data-id="${h.id}"><div class="card-status">${state}</div><div class="card-top"><div class="icon">${h.icon}</div><div><h3>${h.title}</h3><div class="meta"><span class="${h.hot ? 'hot' : ''}">${h.time}</span> ・ ${h.place}${h.distanceKm!==null&&h.distanceKm!==undefined?` ・ ${h.distanceKm}km`:''}</div><div class="meta people" style="margin-top:5px">参加 ${h.current} / ${h.max}人 ・ ${conditions} ${h.distanceKm>10?'<b class="far">・遠め</b>':''}</div></div></div><div class="card-bottom"><div class="host"><span class="mini ${portraitClass(h.photo)}"${photoStyle(h.hostPhoto)} aria-label="${h.host}のプロフィール写真"></span><span>${h.host} ${h.verified?'・確認済み':''}<br><b class="host-tier tier-${(h.hostStatus?.tier||'WHITE').toLowerCase()}">${h.hostStatus?.label||'ホワイト'}</b> ・ ${h.rating}</span></div><span class="match">相性 ${h.match}%</span></div></article>`;
}

async function resetPublicDemo(){if(!confirm('共有デモを初期状態へ戻します。デモ用の募集・申請・チャット・評価がリセットされます。実ユーザーのデータには影響しません。'))return;try{await api('/demo/reset',{method:'POST'});joined.clear();Object.keys(chats).forEach(key=>delete chats[key]);persist();await loadHangouts();home();toast('デモを最初の状態に戻しました')}catch(error){toast(error.message)}}

async function useCurrentLocation(){if(!navigator.geolocation){toast('現在地を取得できないため、エリアを選択してください');return}navigator.geolocation.getCurrentPosition(async(pos)=>{userLocation={latitude:pos.coords.latitude,longitude:pos.coords.longitude,label:'現在地周辺',source:'gps'};persist();await loadHangouts();home();toast('現在地から近い順に並べました')},()=>toast('位置情報を許可するか、エリアを選択してください'),{enableHighAccuracy:false,timeout:8000,maximumAge:300000})}

async function detail(id) {
  const h = hangouts.find((item) => item.id === id);
  if (!h) return;
  const requested = joined.has(id) || h.myJoinStatus === 'PENDING' || h.myJoinStatus === 'ACCEPTED';
  const mine=h.hostUserId===session.user.id||h.host===session.user.displayName;
  let requests=[];
  if(mine){try{requests=await api(`/hangouts/${id}/requests`)}catch(error){toast(error.message)}}
  const state=h.myJoinStatus==='PENDING'?'申請中':h.myJoinStatus==='ACCEPTED'?'承認済み':h.status==='FULL'?'満員':new Date(h.startAt)<=new Date()?'開催中':'募集中';
  const conditionText=`${{ANY:'だれでも',MALE_ONLY:'男性のみ',FEMALE_ONLY:'女性のみ'}[h.genderRestriction]||'だれでも'} ・ ${h.maxAge?h.maxAge===29?'20代まで':h.maxAge===39?'30代まで':'50代まで':'年齢制限なし'}`;
  const chatAvailable=h.myJoinStatus==='ACCEPTED'||(mine&&h.current>1);
  const hangoutChatButton=chatAvailable?'<button class="flow-chat-button inline-chat-button" id="open-flow-chat">このHangoutのチャット</button>':'';
  const approvedRows=(h.acceptedParticipants||[]).map(member=>`<div class="approved-member-row"><span class="request-avatar"${photoStyle(member.profilePhoto)}>${member.profilePhoto?'':safeText(member.displayName).slice(0,1)}</span><div><b>${safeText(member.displayName)}</b><small>${member.gender==='MALE'?'男性':member.gender==='FEMALE'?'女性':'性別非公開'} ・ ${member.verification==='PHONE_VERIFIED'?'電話確認済み':'本人確認前'}</small></div></div>`).join('');
  const participantOverview=`<section class="approved-members"><h3>参加メンバー</h3><small>主催者側 ${h.hostParticipantCount||1}人（男性 ${h.hostMaleCount||0}人・女性 ${h.hostFemaleCount||0}人）</small>${approvedRows||'<p class="empty">承認済みの参加者はまだいません。</p>'}</section>`;
  const navigationButton=(h.locationPrecision==='EXACT'?`<section class="exact-meeting-place"><b>店名</b><span>${safeText(h.meetingPlaceName||h.place)}</span><b>住所</b><span>${safeText(h.meetingAddress||h.place)}</span><button class="navigation-button" id="open-navigation">地図アプリでナビを開始</button></section>`:'')+participantOverview;
  const requestList=mine?`<section class="inline-requests"><div class="inline-requests-head"><div><small>参加申請</small><h3>参加したいメンバー</h3></div><span>${requests.filter(request=>request.status==='PENDING').length}件の判断待ち</span></div>${requests.length?requests.map(request=>`<article class="request-row"><div class="request-person"><span class="request-avatar"${photoStyle(request.user.profilePhoto)}>${request.user.profilePhoto?'':safeText(request.user.displayName).slice(0,1)}</span><div><b>${safeText(request.user.displayName)}</b><small>${request.user.verification==='PHONE_VERIFIED'?'✓ 電話確認済み':'本人確認前'}</small></div></div><p>${safeText(request.message||'メッセージなし')}</p>${request.status==='PENDING'?`<div class="request-decisions"><button class="reject" data-reject="${request.id}">却下</button><button class="approve" data-accept="${request.id}">承認</button></div>`:`<strong class="request-result">${{ACCEPTED:'承認済み',REJECTED:'却下済み',WAITLISTED:'待機中',CANCELLED:'キャンセル'}[request.status]||safeText(request.status)}</strong>`}</article>`).join(''):'<div class="empty inline-request-empty">参加申請はまだありません。</div>'}</section>`:'';
  document.body.insertAdjacentHTML('beforeend', `<div class="sheet hangout-detail-sheet hangout-flow detail-open"><aside class="hangout-flow-list"><header><b>近くのHangout</b><button id="close-flow">一覧を閉じる</button></header>${hangouts.map(item=>`<button class="flow-list-row ${item.id===id?'active':''}" data-flow-hangout="${item.id}"><span class="map-list-photo activity-photo-${item.photo%4}"></span><span><strong>${safeText(item.title)}</strong><small>${safeText(item.time)} ・ ${safeText(item.place)}</small></span></button>`).join('')}</aside><section class="panel hangout-detail-panel"><header class="hangout-detail-nav"><button id="close" class="brand-back" type="button" aria-label="Hangout一覧に戻る"><span></span></button><b>Hangout</b><span></span></header><main class="hangout-detail-content"><div class="hangout-hero-photo activity-photo-${h.photo%4}"></div><div class="hangout-state">${state}</div><div class="detail-head"><div class="detail-photo ${portraitClass(h.photo)}"${photoStyle(h.hostPhoto)} aria-label="${h.host}のプロフィール写真"></div><div><strong>${h.host}</strong><div class="meta">${h.rating} ${h.verified?'・電話確認済み':'・本人確認前'}</div></div></div><div class="eyebrow detail-time">${h.time} ・ 相性 ${h.match}%</div><h2>${h.title}</h2><p>${h.desc}</p><div class="condition-panel"><small>参加条件</small><strong>${conditionText}</strong></div><div class="info"><b>集合場所</b>　${h.place}${h.distanceKm!==null&&h.distanceKm!==undefined?`（約${h.distanceKm}km）`:''}<br><b>参加人数</b>　${h.current} / ${h.max}人<br><b>主催者</b>　${h.host}　${h.rating}<br>${h.locationPrecision==='EXACT'?'承認済み：店名・住所・正確な位置を表示':'承認前：概略エリアのみ表示'}</div>${navigationButton}${h.distanceKm>10?'<div class="distance-warning">移動距離が長めです。開始時刻に間に合うか確認してください。</div>':''}${hangoutChatButton}${requestList}${mine?`<div class="owner-actions"><button id="edit-hangout">内容を編集</button><button id="cancel-hangout">開催を中止</button>${h.status!=='FINISHED'&&h.status!=='CANCELLED'?'<button id="finish-hangout">Hangoutを終了</button>':''}</div>`:''}</main><footer class="hangout-detail-action">${mine?'':`<button class="primary" id="join" ${requested ? 'disabled' : ''}>${requested ? ({PENDING:'申請中',ACCEPTED:'承認済み',REJECTED:'拒否'}[h.myJoinStatus]||'参加申請済み') : '参加したい'}</button>`}</footer></section><section class="chat-conversation" id="chat-conversation"><div class="conversation-placeholder"><span class="conversation-photo activity-photo-${h.photo%4}"></span><b>Hangoutからチャットへ</b><small>参加が承認されると、ここで会話を始められます。</small></div></section></div>`);
  const sheet = document.querySelector('.hangout-flow');
  const backToList=()=>{if(matchMedia('(max-width:699px)').matches)sheet.classList.remove('detail-open','conversation-open');else sheet.remove()};
  sheet.querySelector('#close').onclick = backToList;sheet.querySelector('#close-flow').onclick=()=>sheet.remove();sheet.querySelectorAll('[data-flow-hangout]').forEach(button=>button.onclick=()=>{sheet.remove();detail(button.dataset.flowHangout)});
  const chatButton=sheet.querySelector('#open-flow-chat');if(chatButton)chatButton.onclick=()=>openHangoutFlowChat(id);
  const navigation=sheet.querySelector('#open-navigation');if(navigation)navigation.onclick=()=>window.open(h.navigationUrl||`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(h.latitude!==undefined&&h.longitude!==undefined?`${h.latitude},${h.longitude}`:h.place)}`,'_blank','noopener');
  if(!mine){sheet.querySelector('.hangout-detail-content').insertAdjacentHTML('beforeend','<button class="danger-link" id="report">通報・ブロック</button>');sheet.querySelector('#report').onclick=()=>{sheet.remove();safetyDialog(h)}}
  if(mine){sheet.querySelectorAll('[data-accept]').forEach(button=>button.onclick=()=>decideInlineRequest(id,button.dataset.accept,true,sheet));sheet.querySelectorAll('[data-reject]').forEach(button=>button.onclick=()=>decideInlineRequest(id,button.dataset.reject,false,sheet));sheet.querySelector('#edit-hangout').onclick=()=>showEditHangout(h,sheet);sheet.querySelector('#cancel-hangout').onclick=async()=>{if(!confirm('このHangoutを中止しますか？参加者にも表示されなくなります。'))return;try{await api(`/hangouts/${id}`,{method:'DELETE'});sheet.remove();await loadHangouts();home();toast('Hangoutを中止しました')}catch(error){toast(error.message)}};const finish=sheet.querySelector('#finish-hangout');if(finish)finish.onclick=()=>{sheet.remove();showFinishConfirmation(id)};return}
  sheet.querySelector('#join').onclick = async () => {
    try { await api(`/hangouts/${id}/join`, { method:'POST', body:JSON.stringify({ message:'参加したいです！' }) }); } catch(error) { toast(error.message); return; }
    joined.add(id);
    h.myJoinStatus = 'PENDING';
    chats[id] ||= [{ from: h.host, text: '参加申請ありがとうございます！', mine: false }, { from: h.host, text: '承認後、集合場所をお送りします。', mine: false }];
    persist();
    sheet.remove();
    home();
    toast('参加申請を送りました！ 一覧の人数と状態を更新しました。');
  };
}

async function decideInlineRequest(hangoutId,requestId,accept,sheet){try{await api(`/join-requests/${requestId}/${accept?'accept':'reject'}`,{method:'POST'});sheet.remove();await loadHangouts();await detail(hangoutId);toast(accept?'参加申請を承認しました':'参加申請を却下しました')}catch(error){toast(error.message)}}

async function openHangoutFlowChat(hangoutId){let groups=[];try{groups=await api('/chat-rooms')}catch(error){toast(error.message);return}const room=groups.find(item=>item.hangout.id===hangoutId);if(!room){toast('参加承認後にチャットを開始できます');return}document.querySelector('.hangout-flow')?.classList.add('conversation-open');openChat(room)}

function showEditHangout(h,detailSheet){document.body.insertAdjacentHTML('beforeend',`<div class="host-menu-screen"><header class="host-menu-header"><button id="close" class="brand-back" type="button" aria-label="Hangout画面に戻る"><span></span></button><div><small>主催者メニュー</small><b>Hangoutを編集</b></div><span></span></header><main class="host-menu-content"><section class="host-menu-form"><label>タイトル</label><input id="edit-title" maxlength="80" value="${safeText(h.title)}"><label>承認前に表示するエリア</label><input id="edit-public-place" maxlength="100" value="${safeText(h.publicLocationName)}"><label>承認後に表示する店名・住所</label><input id="edit-place" maxlength="100" value="${safeText(h.place)}"><small class="private-location-note">具体的な集合場所は承認したメンバーだけに表示されます。</small><label>参加できる性別</label><select id="edit-gender"><option value="ANY">だれでも</option><option value="MALE_ONLY">男性のみ</option><option value="FEMALE_ONLY">女性のみ</option></select><label>年齢上限</label><select id="edit-max-age"><option value="">制限なし</option><option value="29">20代まで</option><option value="39">30代まで</option><option value="59">50代まで</option></select><label>説明</label><textarea id="edit-description" maxlength="500" rows="7">${safeText(h.desc)}</textarea></section></main><footer class="host-menu-actions"><button class="secondary" id="cancel-edit">キャンセル</button><button class="primary" id="save-hangout">保存</button></footer></div>`);const menu=document.querySelector('.host-menu-screen');const closeMenu=()=>{menu.classList.remove('open');menu.classList.add('closing');setTimeout(()=>menu.remove(),240)};setTimeout(()=>menu.classList.add('open'),0);menu.querySelector('#edit-gender').value=h.genderRestriction||'ANY';menu.querySelector('#edit-max-age').value=h.maxAge||'';menu.querySelector('#close').onclick=closeMenu;menu.querySelector('#cancel-edit').onclick=closeMenu;menu.querySelector('#save-hangout').onclick=async()=>{try{const maxAge=menu.querySelector('#edit-max-age').value;await api(`/hangouts/${h.id}`,{method:'PATCH',body:JSON.stringify({title:menu.querySelector('#edit-title').value.trim(),publicLocationName:menu.querySelector('#edit-public-place').value.trim(),locationName:menu.querySelector('#edit-place').value.trim(),description:menu.querySelector('#edit-description').value.trim(),genderRestriction:menu.querySelector('#edit-gender').value,maxAge:maxAge?Number(maxAge):null})});closeMenu();await loadHangouts();setTimeout(()=>{detailSheet.remove();detail(h.id)},240);toast('Hangoutと参加条件を更新しました')}catch(error){toast(error.message)}}}

async function manageRequests(id){let requests=[];try{requests=await api(`/hangouts/${id}/requests`)}catch(error){toast(error.message);return}document.body.insertAdjacentHTML('beforeend',`<div class="sheet"><section class="panel"><div class="handle"></div><h2>参加申請</h2>${requests.length?requests.map(r=>`<div class="request-row"><b>${r.user.displayName}</b><span>${r.user.verification==='PHONE_VERIFIED'?'✓ 本人確認済み':'本人確認前'}</span><p>${r.message||'メッセージなし'}</p>${r.status==='PENDING'?`<button class="approve" data-accept="${r.id}">承認</button><button class="reject" data-reject="${r.id}">拒否</button>`:`<strong>${r.status}</strong>`}</div>`).join(''):'<div class="empty">申請はまだありません。</div>'}<button class="secondary" id="close">閉じる</button></section></div>`);const sheet=document.querySelector('.sheet');sheet.querySelector('#close').onclick=()=>sheet.remove();sheet.querySelectorAll('[data-accept]').forEach(b=>b.onclick=async()=>{await api(`/join-requests/${b.dataset.accept}/accept`,{method:'POST'});sheet.remove();manageRequests(id)});sheet.querySelectorAll('[data-reject]').forEach(b=>b.onclick=async()=>{await api(`/join-requests/${b.dataset.reject}/reject`,{method:'POST'});sheet.remove();manageRequests(id)})}

function safetyDialog(h){document.body.insertAdjacentHTML('beforeend',`<div class="sheet"><section class="panel"><div class="handle"></div><h2>${h.host}を通報</h2><label>理由</label><select id="reason"><option value="HARASSMENT">迷惑行為</option><option value="DANGEROUS">危険行為</option><option value="SEXUAL">性的目的</option><option value="SOLICITATION">勧誘・営業</option><option value="FRAUD">詐欺</option><option value="OTHER">その他</option></select><label>詳細</label><textarea id="report-details" rows="3"></textarea><label><input id="block-too" type="checkbox" checked> 同時にブロック</label><button class="primary" id="submit-report">通報する</button><button class="secondary" id="close">キャンセル</button></section></div>`);const sheet=document.querySelector('.sheet');sheet.querySelector('#close').onclick=()=>sheet.remove();sheet.querySelector('#submit-report').onclick=async()=>{try{await api('/safety/reports',{method:'POST',body:JSON.stringify({targetUserId:h.hostUserId,hangoutId:h.id,reason:sheet.querySelector('#reason').value,details:sheet.querySelector('#report-details').value,blockUser:sheet.querySelector('#block-too').checked})});sheet.remove();await loadHangouts();home();toast('通報を受け付け、対象ユーザーを非表示にしました。')}catch(error){toast(error.message)}}}

function showCreate() {
  if(!session.user.profilePhoto){toast('募集作成にはプロフィール写真が必要です');navigate('profileScreen');return}
  if(session.user.verificationStatus!=='PHONE_VERIFIED'){toast('募集作成には電話番号確認が必要です');navigate('profileScreen');return}
  document.body.insertAdjacentHTML('beforeend', `<div class="sheet"><section class="panel"><div class="handle"></div><div class="eyebrow">最短30秒で募集</div><h2>Hangoutを作る</h2><label>何する？</label><input id="title" value="新宿でコーヒー飲もう"><label>いつ？</label><div class="time-grid"><button class="chosen" data-time="30分後">⚡ 30分後</button><button data-time="1時間後">🔥 1時間後</button><button data-time="3時間後">🕒 3時間後</button></div><label>公開エリア（新宿・渋谷のみ）</label><select id="service-area"><option value="SHINJUKU">新宿</option><option value="SHIBUYA">渋谷</option></select><label>承認前に表示するエリア</label><input id="public-place" value="新宿駅周辺"><label>承認後に表示する店名・住所</label><input id="place" value="デモカフェ新宿店 東京都新宿区新宿3-1-1"><small class="private-location-note">店名・住所・正確な位置は承認したメンバーだけに表示されます。</small><label>募集人数</label><select id="capacity"><option value="3">あと2人</option><option value="4">あと3人</option><option value="5">あと4人</option></select><label>参加できる性別</label><select id="gender-restriction"><option value="ANY">だれでも</option><option value="MALE_ONLY">男性のみ</option><option value="FEMALE_ONLY">女性のみ</option></select><label>年齢上限</label><select id="max-age"><option value="">制限なし</option><option value="29">20代まで</option><option value="39">30代まで</option><option value="59">50代まで</option></select><label>ひとこと</label><textarea id="desc" rows="3" placeholder="初参加歓迎！"></textarea><button class="primary" id="publish" style="margin-top:18px">Hangoutを公開する</button><button class="secondary" id="close">キャンセル</button></section></div>`);
  const sheet = document.querySelector('.sheet');
  sheet.querySelector('#close').onclick = () => sheet.remove();
  sheet.querySelectorAll('[data-time]').forEach((button) => button.onclick = () => { sheet.querySelectorAll('[data-time]').forEach((item) => item.classList.remove('chosen')); button.classList.add('chosen'); });
  sheet.querySelector('#service-area').onchange=(event)=>{const shinjuku=event.target.value==='SHINJUKU';sheet.querySelector('#public-place').value=shinjuku?'新宿駅周辺':'渋谷駅周辺';sheet.querySelector('#place').value=shinjuku?'デモカフェ新宿店 東京都新宿区新宿3-1-1':'デモカフェ渋谷店 東京都渋谷区渋谷1-2-3'};
  sheet.querySelector('#publish').onclick = async () => {
    const title = sheet.querySelector('#title').value.trim();
    if (!title) { toast('「何する？」を入力してください。'); return; }
    const time = sheet.querySelector('[data-time].chosen').dataset.time;
    const serviceArea=sheet.querySelector('#service-area').value;const meeting=serviceArea==='SHINJUKU'?areas.新宿:areas.渋谷;
    try { const maxAge=sheet.querySelector('#max-age').value; await api('/hangouts',{method:'POST',body:JSON.stringify({title,description:sheet.querySelector('#desc').value.trim()||'一緒に楽しい時間を過ごしましょう！',category:'CAFE',serviceArea,startInMinutes:{'30分後':30,'1時間後':60,'3時間後':180}[time],publicLocationName:sheet.querySelector('#public-place').value.trim(),locationName:sheet.querySelector('#place').value.trim(),latitude:meeting.latitude,longitude:meeting.longitude,maxParticipants:Number(sheet.querySelector('#capacity').value),genderRestriction:sheet.querySelector('#gender-restriction').value,...(maxAge?{maxAge:Number(maxAge)}:{})})}); await loadHangouts(); } catch(error) { toast(error.message); return; }
    persist();
    activeFilter = 'おすすめ';
    sheet.remove();
    home();
    toast('Hangoutを公開し、一覧の先頭へ追加しました！');
  };
}

function mapScreen() {
  activeScreen = 'mapScreen';
  shell(`<section class="page-title"><div class="eyebrow">${userLocation?.label||'エリアを選択してください'}・概略位置</div><h1>近くのマップ</h1></section><section class="map"><div class="road r1"></div><div class="road r2"></div>${hangouts.slice(0,5).map((h,i)=>`<button class="pin photo-pin p${i} activity-photo-${h.photo%4}" data-id="${h.id}" aria-label="${h.title}"><span>${h.distanceKm!==null&&h.distanceKm!==undefined?h.distanceKm+'km':h.time}</span></button>`).join('')}<div class="you">${userLocation?'現在地':'基準点'}</div></section><div class="map-linked-list">${hangouts.slice(0,5).map(h=>`<button data-map-card="${h.id}"><span class="map-list-photo activity-photo-${h.photo%4}"></span><b>${h.title}</b><span>${h.distanceKm!==null&&h.distanceKm!==undefined?h.distanceKm+'km ・ ':''}${h.time}</span></button>`).join('')}</div><div class="map-note">写真と募集一覧が連動します。承認前は概略位置、承認後だけ正確な集合地点を表示します。</div>`, false);
  document.querySelectorAll('.pin').forEach((pin)=>pin.onclick=()=>{document.querySelectorAll('[data-map-card]').forEach(b=>b.classList.toggle('active',b.dataset.mapCard===pin.dataset.id));document.querySelector(`[data-map-card="${pin.dataset.id}"]`)?.scrollIntoView({behavior:'smooth',block:'nearest'})});
  document.querySelectorAll('[data-map-card]').forEach((button)=>button.onclick=()=>detail(button.dataset.mapCard));
}

async function chatScreen() {
  activeScreen = 'chatScreen';
  let groups=[],directs=[];try{[groups,directs]=await Promise.all([api('/chat-rooms'),api('/direct-chats')])}catch(error){toast(error.message)}
  const groupRows=groups.map((r,i)=>`<div class="group-chat-card"><button class="chat-row" data-room-index="${i}" data-kind="group"><span class="mini ${portraitClass(i%4)}"${photoStyle(r.hangout.host.profilePhoto)}></span><span><b>${safeText(r.hangout.title)}</b><small>${r.members.length}人 ・ ${safeText(r.lastMessage?.body||'グループにメッセージを送りましょう')}</small></span><em>${r.hangout.status==='FINISHED'?'終了・評価待ち':'グループ'}</em></button><div class="member-actions">${r.members.filter(member=>member.id!==session.user.id).map(member=>member.directChatEligible?`<button data-start-direct="${member.id}">${safeText(member.displayName)}と1対1</button>`:r.hangout.status==='FINISHED'?`<button data-rate-user="${member.id}" data-hangout-id="${r.hangout.id}" data-user-name="${safeText(member.displayName)}">${safeText(member.displayName)}を評価${member.myRatingScore?`（★${member.myRatingScore}）`:''}</button><span class="direct-locked">${member.myRatingScore===5?'相手の★5待ち':'評価待ち'} ・ 双方★5で1対1解放</span>`:'').join('')}</div></div>`).join('');
  const directRows=directs.map((r,i)=>`<button class="chat-row" data-room-index="${i}" data-kind="direct"><span class="mini ${portraitClass((i+1)%4)}"${photoStyle(r.otherUser.profilePhoto)}></span><span><b>${safeText(r.otherUser.displayName)}</b><small>${safeText(r.lastMessage?.body||'1対1でメッセージを送りましょう')}</small></span><em>1対1</em></button>`).join('');
  const demoChatHint=demoRole?`<div class="demo-chat-hint"><span>${demoRole==='host'?'終了操作は左のHangout詳細から行います':'終了後に主催者を★1〜5で評価（双方★5なら1対1）'}</span><button id="chat-switch-demo-role">役割切替</button></div>`:'';
  const hosted=demoRole==='host'?hangouts.filter(h=>h.hostUserId===session.user.id):[];const hangoutRail=demoRole==='host'?`<aside class="hangout-rail"><header><b>Hangout <i>Now</i></b><span>主催中のHangout</span></header><div class="hosted-hangouts">${hosted.map(h=>`<article><button class="hosted-photo activity-photo-${h.photo%4}" data-open-host-hangout="${h.id}" aria-label="${safeText(h.title)}を開く"></button><div><strong>${safeText(h.title)}</strong><small>${safeText(h.time)} ・ ${safeText(h.place)}</small><button data-hangout-chat="${h.id}">チャットを見る</button></div></article>`).join('')||'<div class="empty">主催中のHangoutはありません。</div>'}</div></aside>`:'';
  shell(`<section class="chat-workspace ${demoRole==='host'?'with-hangout-rail':''}">${hangoutRail}<aside class="chat-sidebar"><section class="page-title chat-page-title"><button class="brand-back chat-list-back" type="button" aria-label="Hangout一覧に戻る"><span></span></button><div><div class="eyebrow">会話から次の行動へ</div><h1>チャット</h1></div><span class="realtime-pill">● リアルタイム</span></section>${demoChatHint}<div class="chat-tabs"><button class="active" data-chat-tab="group">グループ <b>${groups.length}</b></button><button data-chat-tab="direct">1対1 <b>${directs.length}</b></button></div><div class="chat-lists"><section class="chat-list" data-chat-list="group">${groupRows||'<div class="empty">参加が承認されるとグループチャットが表示されます。</div>'}</section><section class="chat-list hidden" data-chat-list="direct">${directRows||'<div class="empty">双方の★5評価がそろうと1対1チャットが表示されます。</div>'}</section></div></aside><section class="chat-conversation" id="chat-conversation"><div class="conversation-placeholder"><span class="conversation-photo"></span><b>会話を選んでください</b><small>相手の表情を感じながら、待ち合わせまで自然に話せます。</small></div></section></section>`, false);
  document.querySelector('.phone').classList.add('chat-phone');
  const chatSwitch=document.querySelector('#chat-switch-demo-role');if(chatSwitch)chatSwitch.onclick=()=>{realtimeSocket?.disconnect();session=null;demoRole=null;localStorage.removeItem('hangout-now-session');localStorage.removeItem('hangout-now-demo-role');authScreen('login')};
  document.querySelectorAll('[data-chat-tab]').forEach((tab)=>tab.onclick=()=>{document.querySelectorAll('[data-chat-tab]').forEach(x=>x.classList.toggle('active',x===tab));document.querySelectorAll('[data-chat-list]').forEach(x=>x.classList.toggle('hidden',x.dataset.chatList!==tab.dataset.chatTab))});
  document.querySelectorAll('[data-room-index]').forEach((button)=>button.onclick=()=>{const room=(button.dataset.kind==='direct'?directs:groups)[Number(button.dataset.roomIndex)];openChat(room)});
  document.querySelectorAll('[data-start-direct]').forEach((button)=>button.onclick=async()=>{try{await api('/direct-chats',{method:'POST',body:JSON.stringify({userId:button.dataset.startDirect})});await chatScreen();document.querySelector('[data-chat-tab="direct"]')?.click()}catch(error){toast(error.message)}});
  document.querySelectorAll('[data-open-host-hangout]').forEach(button=>button.onclick=()=>detail(button.dataset.openHostHangout));document.querySelectorAll('[data-hangout-chat]').forEach(button=>button.onclick=()=>{const workspace=document.querySelector('.chat-workspace');workspace.classList.add('hangout-selected');const row=[...document.querySelectorAll('.chat-row[data-kind="group"]')].find(item=>groups[Number(item.dataset.roomIndex)]?.hangout.id===button.dataset.hangoutChat);row?.click()});const listBack=document.querySelector('.chat-list-back');if(listBack)listBack.onclick=()=>document.querySelector('.chat-workspace').classList.remove('hangout-selected','conversation-open');
  document.querySelectorAll('[data-rate-user]').forEach((button)=>button.onclick=()=>showRatingDialog(button.dataset.hangoutId,button.dataset.rateUser,button.dataset.userName));
}

function showRatingDialog(hangoutId,ratedUserId,userName){document.body.insertAdjacentHTML('beforeend',`<div class="sheet rating-sheet"><section class="panel"><div class="handle"></div><div class="rating-person">${safeText(userName)}さんとのHangout</div><h2>評価を選んでください</h2><p>★1〜4も評価として保存されます。双方が★5の場合だけ1対1チャットが解放されます。</p><div class="rating-stars">${[1,2,3,4,5].map(score=>`<button data-rating-score="${score}" aria-label="星${score}">${'★'.repeat(score)}<small>${score}</small></button>`).join('')}</div><button class="secondary" data-cancel-rating>キャンセル</button></section></div>`);const sheet=document.querySelector('.rating-sheet');sheet.querySelector('[data-cancel-rating]').onclick=()=>sheet.remove();sheet.querySelectorAll('[data-rating-score]').forEach(button=>button.onclick=async()=>{const score=Number(button.dataset.ratingScore);try{await api(`/hangouts/${hangoutId}/ratings`,{method:'POST',body:JSON.stringify({ratedUserId,score})});sheet.remove();toast(`★${score}の評価を保存しました${score===5?'。相手も★5なら1対1が解放されます':''}`);chatScreen()}catch(error){toast(error.message)}})}

async function notificationScreen(){activeScreen='notifications';const data=await loadNotificationCount()||{items:[],enabled:true};shell(`<section class="page-title"><div class="eyebrow">リアルタイム更新</div><h1>通知</h1></section><div class="notification-settings"><label><input id="notification-enabled" type="checkbox" ${data.enabled?'checked':''}> アプリ内通知を受け取る</label><button id="browser-notification">端末通知を許可</button><button id="read-all">すべて既読</button></div><section class="notification-list">${data.items.length?data.items.map(n=>`<button data-notification="${n.id}" class="notification-item ${n.readAt?'':'unread'}"><b>${n.title}</b><span>${n.body}</span><small>${new Date(n.createdAt).toLocaleString('ja-JP')}</small></button>`).join(''):'<div class="empty">通知はまだありません。</div>'}</section>`,false);document.querySelector('#notification-enabled').onchange=async(e)=>{await api('/notifications/settings',{method:'PATCH',body:JSON.stringify({enabled:e.target.checked})});toast('通知設定を保存しました')};document.querySelector('#browser-notification').onclick=async()=>{if(!('Notification'in window)){toast('この端末は通知に対応していません');return}const result=await Notification.requestPermission();toast(result==='granted'?'端末通知を許可しました':'アプリ内通知を利用します')};document.querySelector('#read-all').onclick=async()=>{await api('/notifications/read-all',{method:'POST'});unreadNotifications=0;notificationScreen()};document.querySelectorAll('[data-notification]').forEach(b=>b.onclick=async()=>{await api(`/notifications/${b.dataset.notification}/read`,{method:'POST'});b.classList.remove('unread');await loadNotificationCount()})}

function stampContent(body){if(!body?.startsWith('__STAMP__'))return null;try{return JSON.parse(body.slice(9))}catch{return null}}
function safeText(value){return String(value).replace(/[&<>"']/g,(character)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]))}
function messageContent(body){const stamp=stampContent(body);return stamp?`<div class="stamp-message"><img src="${safeText(stamp.imageUrl)}" alt=""><b>${safeText(stamp.text)}</b></div>`:safeText(body)}

async function openChat(room) {
  const kind=room.type==='DIRECT'?'direct':'group';const base=kind==='direct'?'/direct-chats':'/chat-rooms';
  let messages=[],stamps=[];try{[messages,stamps]=await Promise.all([api(`${base}/${room.id}/messages`),api('/stamps')])}catch(error){toast(error.message);return}
  const title=kind==='direct'?room.otherUser.displayName:room.hangout.title;const photo=kind==='direct'?room.otherUser.profilePhoto:room.hangout.host.profilePhoto;
  const conversation=document.querySelector('#chat-conversation');const workspace=document.querySelector('.chat-workspace,.hangout-flow');
  conversation.innerHTML=`<header class="chat-conversation-head"><button class="chat-back brand-back" type="button" aria-label="チャット一覧に戻る"><span></span></button><span class="conversation-avatar"${photoStyle(photo)}>${photo?'':safeText(title).slice(0,1)}</span><div><h2>${safeText(title)}</h2><small>${kind==='direct'?'1対1':room.hangout.status==='FINISHED'?'終了・評価待ち':'グループ ・ '+room.members.length+'人'}　<span>● オンライン</span></small></div></header><div class="messages">${messages.map((m)=>{const mine=m.senderUserId===session.user.id;return `<div class="message-line ${mine?'mine':''}">${mine?'':`<span class="message-avatar"${photoStyle(m.sender.profilePhoto)}>${m.sender.profilePhoto?'':safeText(m.sender.displayName).slice(0,1)}</span>`}<div class="bubble-wrap"><small>${safeText(m.sender.displayName)}</small><div class="bubble">${messageContent(m.body)}</div><time>${new Date(m.createdAt).toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit'})}</time></div>${mine?`<span class="message-avatar"${photoStyle(m.sender.profilePhoto||session.user.profilePhoto)}>${m.sender.profilePhoto||session.user.profilePhoto?'':safeText(m.sender.displayName).slice(0,1)}</span>`:''}</div>`}).join('')||'<div class="empty">最初のメッセージを送ってみましょう。</div>'}</div><div class="conversation-actions"><div class="stamp-tray">${stamps.map(stamp=>`<button data-stamp="${stamp.id}" class="stamp-choice"><img src="${safeText(stamp.imageUrl)}" alt="${safeText(stamp.text)}"><b>${safeText(stamp.text)}</b></button>`).join('')}<button class="stamp-create">＋<small>スタンプ作成</small></button></div>${kind==='group'?'<div class="quick"><button>向かっています</button><button>少し遅れます</button><button>到着しました</button></div>':''}<div class="composer"><input placeholder="メッセージを入力" maxlength="1000"><button>送信</button></div></div>`;
  workspace.classList.add('conversation-open');conversation.querySelector('.messages').scrollTop=conversation.querySelector('.messages').scrollHeight;
  conversation.querySelector('.chat-back').onclick=()=>workspace.classList.remove('conversation-open');
  const send=async(text,stampId)=>{if(!stampId&&!text.trim())return;try{await api(`${base}/${room.id}/messages`,{method:'POST',body:JSON.stringify(stampId?{stampId}:{body:text.trim()})});openChat(room)}catch(error){toast(error.message)}};
  conversation.querySelectorAll('.quick button').forEach((button)=>button.onclick=()=>send(button.textContent));
  conversation.querySelectorAll('[data-stamp]').forEach((button)=>button.onclick=()=>send('',button.dataset.stamp));
  conversation.querySelector('.stamp-create').onclick=()=>showStampCreator(()=>openChat(room));
  conversation.querySelector('.composer button').onclick=()=>send(conversation.querySelector('.composer input').value);
  conversation.querySelector('.composer input').onkeydown=(event)=>{if(event.key==='Enter'&&!event.isComposing)send(event.currentTarget.value)};
}

function showFinishConfirmation(hangoutId){document.body.insertAdjacentHTML('beforeend',`<div class="sheet finish-sheet"><section class="panel"><div class="handle"></div><div class="eyebrow">Hangoutを終了</div><h2>楽しい時間を過ごせましたか？</h2><p>終了すると参加者を★1〜5で評価できます。双方が★5の場合だけ1対1チャットが解放されます。</p><button class="primary" id="confirm-finish">終了して評価へ進む</button><button class="secondary" id="close">まだ終了しない</button></section></div>`);const sheet=document.querySelector('.finish-sheet');sheet.querySelector('#close').onclick=()=>sheet.remove();sheet.querySelector('#confirm-finish').onclick=async()=>{try{await api(`/hangouts/${hangoutId}/finish`,{method:'POST'});sheet.remove();await loadHangouts();toast('Hangoutを終了しました。チャット画面から参加者を評価できます');home()}catch(error){toast(error.message)}}}

function showStampCreator(done){document.body.insertAdjacentHTML('beforeend',`<div class="sheet stamp-creator-sheet"><section class="panel"><div class="handle"></div><h2>写真スタンプを作る</h2><label>写真</label><input id="stamp-photo" type="file" accept="image/jpeg,image/png,image/webp"><label>文字</label><div class="stamp-phrases"><button>向かってます</button><button>少し遅れます</button><button>到着</button></div><input id="stamp-text" maxlength="30" value="向かってます"><p class="stamp-note">作成したスタンプは自分だけに保存され、配布されません。</p><button class="primary" id="save-stamp">保存</button><button class="secondary" id="cancel-stamp">キャンセル</button></section></div>`);const creator=document.querySelector('.stamp-creator-sheet');creator.querySelectorAll('.stamp-phrases button').forEach(button=>button.onclick=()=>creator.querySelector('#stamp-text').value=button.textContent);creator.querySelector('#cancel-stamp').onclick=()=>creator.remove();creator.querySelector('#save-stamp').onclick=async()=>{try{const file=creator.querySelector('#stamp-photo').files[0];const imageDataValue=file?await imageData(file):undefined;await api('/stamps',{method:'POST',body:JSON.stringify({text:creator.querySelector('#stamp-text').value.trim(),...(imageDataValue?{imageData:imageDataValue}:{})})});creator.remove();done();toast('自分用スタンプを保存しました')}catch(error){toast(error.message)}}}

async function profileScreen() {
  activeScreen = 'profileScreen';
  const hosted=hangouts.filter((h)=>h.host==='あなた').length;
  const verified=session.user.verificationStatus==='PHONE_VERIFIED';
  let hostStatus=null;try{hostStatus=await api('/users/me/host-status')}catch(error){toast(error.message)}
  shell(`<section class="profile"><div class="profile-photo avatar"${photoStyle(session.user.profilePhoto)}></div><h1>${session.user.displayName}</h1><div class="verified ${verified?'':'unverified'}">${verified?'✓ 電話番号確認済み':'電話番号未確認'}</div><p>${session.user.bio||'自己紹介を登録しましょう。'}</p><div class="profile-actions"><label class="upload-button">写真を変更<input id="profile-photo" type="file" accept="image/jpeg,image/png,image/webp"></label><button class="outline" id="verify-phone">${verified?'電話番号を変更':'電話番号を確認'}</button></div><div class="stats"><div><b>4.9</b><span>評価</span></div><div><b>${joined.size}</b><span>参加</span></div><div><b>${hosted}</b><span>主催</span></div></div><h2>興味のあること</h2><div class="tags">${(session.user.interests||[]).map(i=>`<span>${i}</span>`).join('')||'<span>未登録</span>'}</div><div class="safety">🛡️ 募集を作るには、顔が分かるプロフィール写真と電話番号確認が必要です。</div></section>`, false);
  if(hostStatus){const nextLabel={BRONZE:'ブロンズ',SILVER:'シルバー',GOLD:'ゴールド',PLATINUM:'プラチナ',DIAMOND:'ダイアモンド'}[hostStatus.nextTier];document.querySelector('.profile .verified').insertAdjacentHTML('afterend',`<section class="host-rank-card tier-${hostStatus.tier.toLowerCase()}"><small>主催者ステータス</small><strong>${hostStatus.label}</strong><p>開催完了 ${hostStatus.completedHangouts}回 ・ 累計参加者 ${hostStatus.totalParticipants}人<br>平均 ${hostStatus.averageRating??'未評価'} ・ 評価 ${hostStatus.ratingCount}件 ・ 中止率 ${Math.round(hostStatus.cancellationRate*100)}%</p><em>${nextLabel?`次のステータス：${nextLabel}`:'最高ステータスです'}</em></section>`);const stats=document.querySelectorAll('.stats b');stats[0].textContent=hostStatus.averageRating??'—';stats[2].textContent=hostStatus.completedHangouts;document.querySelectorAll('.stats span')[0].textContent='主催評価';document.querySelectorAll('.stats span')[2].textContent='開催完了'}
  document.querySelector('.profile-actions').insertAdjacentHTML('afterend',`<label class="profile-gender-label">性別<select id="profile-gender"><option value="UNDISCLOSED">回答しない</option><option value="MALE">男性</option><option value="FEMALE">女性</option><option value="OTHER">その他</option></select></label>`);
  document.querySelector('#profile-gender').value=session.user.gender||'UNDISCLOSED';
  document.querySelector('#profile-gender').onchange=async(event)=>{try{session.user=await api('/users/me',{method:'PATCH',body:JSON.stringify({gender:event.target.value})});saveSession();toast('性別を更新しました')}catch(error){toast(error.message)}};
  document.querySelector('#profile-photo').onchange=async(event)=>{const file=event.target.files[0];if(!file)return;try{const profilePhoto=await imageData(file);session.user=await api('/users/me',{method:'PATCH',body:JSON.stringify({profilePhoto})});saveSession();profileScreen();toast('プロフィール写真を更新しました')}catch(error){toast(error.message)}};
  document.querySelector('#verify-phone').onclick=phoneDialog;
}

function showCreate() {
  if(!session.user.profilePhoto){toast('Hangoutの作成にはプロフィール写真が必要です');navigate('profileScreen');return}
  if(session.user.verificationStatus!=='PHONE_VERIFIED'){toast('Hangoutの作成には電話番号確認が必要です');navigate('profileScreen');return}
  document.body.insertAdjacentHTML('beforeend', `<div class="create-hangout-screen"><header class="host-menu-header"><button id="close-create" class="brand-back" type="button" aria-label="ホームに戻る"><span></span></button><div><small>新しい募集</small><b>Hangoutを作る</b></div><span></span></header><main class="host-menu-content"><section class="host-menu-form"><label>何する？</label><input id="title" maxlength="80" value="新宿でコーヒー飲もう"><label>いつ？</label><div class="time-grid"><button class="chosen" data-time="30">⚡ 30分後</button><button data-time="60">🔥 1時間後</button><button data-time="180">🕒 3時間後</button></div><label>公開エリア（新宿・渋谷のみ）</label><select id="service-area"><option value="SHINJUKU">新宿</option><option value="SHIBUYA">渋谷</option></select><label>承認前に表示するエリア</label><input id="public-place" maxlength="100" value="新宿駅周辺"><div class="private-place-box"><strong>承認後に表示する集合場所</strong><small>店名・住所・ナビ情報は承認したメンバーだけに表示します。</small><label>店名</label><input id="meeting-place-name" maxlength="100" value="デモカフェ新宿店"><label>住所</label><input id="meeting-address" maxlength="200" value="東京都新宿区新宿3-1-1"><label>ナビアプリの共有URL（任意）</label><input id="navigation-url" type="url" maxlength="500" placeholder="Googleマップなどの共有URLを貼り付け"><div class="map-input-actions"><button type="button" id="open-map-search">Googleマップで場所を検索</button><button type="button" id="make-map-link">店名・住所からナビを設定</button></div><small id="map-help">ナビアプリで店名を検索し、共有URLを貼り付けるだけで設定できます。</small></div><label>主催者側の人数</label><div class="host-party-grid"><label>男性<select id="host-male-count">${[0,1,2,3,4,5].map(n=>`<option value="${n}" ${n===1?'selected':''}>${n}人</option>`).join('')}</select></label><label>女性<select id="host-female-count">${[0,1,2,3,4,5].map(n=>`<option value="${n}">${n}人</option>`).join('')}</select></label></div><small>例：男性2人なら、参加を検討している人にも「男性2人」と表示されます。</small><label>合計人数（主催者側を含む）</label><select id="capacity">${[3,4,5,6,8,10,12].map(n=>`<option value="${n}" ${n===4?'selected':''}>${n}人</option>`).join('')}</select><label>参加できる性別</label><select id="gender-restriction"><option value="ANY">だれでも</option><option value="MALE_ONLY">男性のみ</option><option value="FEMALE_ONLY">女性のみ</option></select><label>年齢上限</label><select id="max-age"><option value="">制限なし</option><option value="29">20代まで</option><option value="39">30代まで</option><option value="59">50代まで</option></select><label>ひとこと</label><textarea id="desc" rows="4" placeholder="初参加歓迎！"></textarea></section></main><footer class="host-menu-actions"><button class="secondary" id="cancel-create">キャンセル</button><button class="primary" id="publish">Hangoutを公開する</button></footer></div>`);
  const screen=document.querySelector('.create-hangout-screen');const close=()=>{screen.classList.add('closing');setTimeout(()=>screen.remove(),240)};setTimeout(()=>screen.classList.add('open'),0);screen.querySelector('#close-create').onclick=close;screen.querySelector('#cancel-create').onclick=close;
  screen.querySelectorAll('[data-time]').forEach(button=>button.onclick=()=>{screen.querySelectorAll('[data-time]').forEach(item=>item.classList.remove('chosen'));button.classList.add('chosen')});
  screen.querySelector('#service-area').onchange=event=>{const shinjuku=event.target.value==='SHINJUKU';screen.querySelector('#public-place').value=shinjuku?'新宿駅周辺':'渋谷駅周辺';screen.querySelector('#meeting-place-name').value=shinjuku?'デモカフェ新宿店':'デモカフェ渋谷店';screen.querySelector('#meeting-address').value=shinjuku?'東京都新宿区新宿3-1-1':'東京都渋谷区渋谷1-2-3'};
  const mapQuery=()=>encodeURIComponent(`${screen.querySelector('#meeting-place-name').value.trim()} ${screen.querySelector('#meeting-address').value.trim()}`);screen.querySelector('#open-map-search').onclick=()=>window.open(`https://www.google.com/maps/search/?api=1&query=${mapQuery()}`,'_blank','noopener');screen.querySelector('#make-map-link').onclick=()=>{screen.querySelector('#navigation-url').value=`https://www.google.com/maps/search/?api=1&query=${mapQuery()}`;screen.querySelector('#map-help').textContent='店名・住所からナビURLを設定しました。'};
  screen.querySelector('#publish').onclick=async()=>{const title=screen.querySelector('#title').value.trim();const placeName=screen.querySelector('#meeting-place-name').value.trim();const address=screen.querySelector('#meeting-address').value.trim();const male=Number(screen.querySelector('#host-male-count').value);const female=Number(screen.querySelector('#host-female-count').value);const capacity=Number(screen.querySelector('#capacity').value);if(!title||!placeName||!address){toast('タイトル、店名、住所を入力してください');return}if(male+female<1){toast('主催者側は1人以上にしてください');return}if(male+female>=capacity){toast('合計人数は主催者側の人数より多くしてください');return}const serviceArea=screen.querySelector('#service-area').value;const meeting=serviceArea==='SHINJUKU'?areas.新宿:areas.渋谷;const navigationUrl=screen.querySelector('#navigation-url').value.trim()||`https://www.google.com/maps/search/?api=1&query=${mapQuery()}`;try{const maxAge=screen.querySelector('#max-age').value;await api('/hangouts',{method:'POST',body:JSON.stringify({title,description:screen.querySelector('#desc').value.trim()||'一緒に楽しい時間を過ごしましょう！',category:'CAFE',serviceArea,startInMinutes:Number(screen.querySelector('[data-time].chosen').dataset.time),publicLocationName:screen.querySelector('#public-place').value.trim(),locationName:`${placeName} ${address}`,meetingPlaceName:placeName,meetingAddress:address,navigationUrl,latitude:meeting.latitude,longitude:meeting.longitude,maxParticipants:capacity,hostMaleCount:male,hostFemaleCount:female,genderRestriction:screen.querySelector('#gender-restriction').value,...(maxAge?{maxAge:Number(maxAge)}:{})})});await loadHangouts();close();home();toast('Hangoutを公開し、一覧へ追加しました')}catch(error){toast(error.message)}};
}

function saveSession(){localStorage.setItem('hangout-now-session',JSON.stringify(session))}
function imageData(file){return new Promise((resolve,reject)=>{if(file.size>8*1024*1024){reject(new Error('画像は8MB以下にしてください'));return}const reader=new FileReader();reader.onerror=()=>reject(new Error('画像を読み込めません'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('画像形式を確認してください'));img.onload=()=>{const size=Math.min(512,Math.max(img.width,img.height));const scale=size/Math.max(img.width,img.height);const canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.84))};img.src=reader.result};reader.readAsDataURL(file)})}
function phoneDialog(){document.body.insertAdjacentHTML('beforeend',`<div class="sheet"><section class="panel"><div class="handle"></div><h2>電話番号確認</h2><p>国番号から入力してください。開発デモでは確認コードをこの画面に表示します。</p><label>電話番号</label><input id="phone" type="tel" value="${session.user.phoneNumber||'+8190'}"><div id="phone-code-area" class="hidden"><label>6桁の確認コード</label><input id="phone-code" inputmode="numeric" maxlength="6"><small id="demo-code"></small></div><button class="primary" id="phone-action">確認コードを送る</button><button class="secondary" id="close">キャンセル</button></section></div>`);const sheet=document.querySelector('.sheet');sheet.querySelector('#close').onclick=()=>sheet.remove();let requested=false;sheet.querySelector('#phone-action').onclick=async()=>{try{const phone=sheet.querySelector('#phone').value.trim();if(!requested){const result=await api('/users/me/phone/request',{method:'POST',body:JSON.stringify({phone})});requested=true;sheet.querySelector('#phone-code-area').classList.remove('hidden');sheet.querySelector('#demo-code').textContent=result.demoCode?`デモ確認コード：${result.demoCode}`:'SMSに確認コードを送信しました';sheet.querySelector('#phone-action').textContent='電話番号を確認';return}session.user=await api('/users/me/phone/confirm',{method:'POST',body:JSON.stringify({phone,code:sheet.querySelector('#phone-code').value})});saveSession();sheet.remove();profileScreen();toast('電話番号を確認しました')}catch(error){toast(error.message)}}}

function toast(text) {
  document.querySelector('.toast')?.remove();
  document.body.insertAdjacentHTML('beforeend', `<div class="toast">✓ ${text}</div>`);
  setTimeout(() => document.querySelector('.toast')?.remove(), 3000);
}

window.addEventListener('online',connectRealtime);window.addEventListener('offline',()=>document.body.classList.add('realtime-offline'));
if (session) {connectRealtime();loadNotificationCount();loadHangouts().then(()=>navigate('home')).catch(()=>navigate('home'))} else authScreen();
